const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig");
fn go(rig: *rigz.Rig, mode: task.Mode, name: []const u8, args: task.Args) !u32 { var cx = rig.ctx(mode); return jrun.run(&cx, jobs.find(name).?, args); }
fn must(rig: *rigz.Rig, prefix: []const u8) !void { if (!rig.waitPre(prefix, 4000)) { std.debug.print("missing record: {s}\n", .{prefix}); return error.TestUnexpectedResult; } }
fn lots(rig: *rigz.Rig) void { rig.conf.capz_acct_dayz = 99; rig.conf.capz_prod_dayz = 99; rig.conf.capz_data_dayz = 99; rig.conf.capz_mone_dayz = 99; rig.conf.capz_acce_dayz = 99; rig.conf.capz_sett_dayz = 99; rig.conf.capz_help_dayz = 99; }
test "catalog: unique names, first step is goto, steps carry what they need" { for (jobs.JOBS, 0..) |jb, ix| { for (jobs.JOBS[ix + 1 ..]) |oth| try std.testing.expect(!std.mem.eql(u8, jb.name, oth.name)); try std.testing.expect(jb.steps.len >= 1); try std.testing.expect(jb.steps[0].op == .goto); try std.testing.expect(jb.hint.len > 0); } try std.testing.expect(jobs.JOBS.len >= 50); }
test "catalog: irreversible jobs are risky, reads are not" { const risky = [_][]const u8{ "account-delete", "sub-cancel", "plan-change", "topup-buy", "key-revoke", "email-change", "pass-change", "twofa-off", "team-remove", "webhook-drop", "crawl-stop", "payment-open" }; for (risky) |nam| try std.testing.expect(jobs.find(nam).?.risk == .x); const safe = [_][]const u8{ "usage-view", "plan-view", "logs-view", "login", "signup", "key-create", "fetch-run" }; for (safe) |nam| try std.testing.expect(jobs.find(nam).?.risk == .w); try std.testing.expect(jobs.find("signup").?.once and jobs.find("account-delete").?.once and jobs.find("sub-cancel").?.once); try std.testing.expect(jobs.find("login").?.auth and !jobs.find("key-create").?.auth); }
test "dry-run shows the plan and changes nothing for every job" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_acct_dayz = 99; const args: task.Args = .{ .text = "t", .to = "a@b.co", .url = "/usage", .title = "T", .price = "5", .desc = "d", .group = "g", .photo = "p.jpg", .opt = "o" }; for (jobs.JOBS) |jb| { try std.testing.expectEqual(@as(u32, 1), try go(&rig, .dry, jb.name, args)); } try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try std.testing.expect(std.mem.find(u8, rig.sink.items, "dry-run: preview only") != null); }
test "args are checked and secrets are required for live login" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectError(error.BadUsage, go(&rig, .live, "verify-email", .{})); try std.testing.expectError(error.BadUsage, go(&rig, .live, "fetch-run", .{})); var cx = rig.ctx(.live); cx.secr_user = ""; cx.secr_pass = ""; try std.testing.expectError(error.NoSecret, jrun.run(&cx, jobs.find("login").?, .{})); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "account: signup types the saved login, once-only; verify, login, logout, reset" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "signup", .{})); try must(&rig, "btn|Create account|tester@example.com|pw-secret-1"); try std.testing.expectEqual(@as(u32, 0), try go(&rig, .live, "signup", .{})); try std.testing.expect(std.mem.find(u8, rig.sink.items, "already done earlier") != null); _ = try go(&rig, .live, "verify-email", .{ .text = "123456" }); try must(&rig, "btn|Verify|123456"); _ = try go(&rig, .live, "login", .{}); try must(&rig, "btn|Log in|tester@example.com|pw-secret-1"); _ = try go(&rig, .live, "logout", .{}); try must(&rig, "btn|Log out"); _ = try go(&rig, .live, "reset-pass", .{}); try must(&rig, "btn|Send reset link|tester@example.com"); }
test "account: sso buttons, profile name, 2FA on, risky changes need force" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "sso-google", .{}); try must(&rig, "btn|Continue with Google"); _ = try go(&rig, .live, "sso-github", .{}); try must(&rig, "btn|Continue with GitHub"); _ = try go(&rig, .live, "profile-name", .{ .title = "Kim Doe" }); try must(&rig, "btn|Save|Kim Doe|"); _ = try go(&rig, .live, "twofa-on", .{}); try must(&rig, "tog|Two-factor authentication=on"); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "email-change", .{ .to = "new@example.com" })); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "account-delete", .{})); _ = try go(&rig, .force, "email-change", .{ .to = "new@example.com" }); try must(&rig, "btn|Save|Old Name|new@example.com"); _ = try go(&rig, .force, "pass-change", .{ .opt = "newpw-1" }); try must(&rig, "btn|Change password|pw-secret-1|newpw-1"); _ = try go(&rig, .force, "twofa-off", .{}); _ = try go(&rig, .force, "account-delete", .{}); try must(&rig, "btn|Delete|"); }
test "products: fetch with raw params and language, extract, snippet, crawl, batch, browser, proxy" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "fetch-run", .{ .url = "https://example.com", .opt = "json_response=true", .text = "python" }); try must(&rig, "btn|Run|https://example.com|json_response=true"); try must(&rig, "opt|Language=python"); _ = try go(&rig, .live, "extract-run", .{ .url = "https://example.com", .opt = "title=h1" }); try must(&rig, "btn|Run|https://example.com|title=h1"); _ = try go(&rig, .live, "snippet-get", .{ .url = "https://example.com", .text = "curl" }); try must(&rig, "btn|Show code"); _ = try go(&rig, .live, "crawl-start", .{ .url = "https://example.com" }); try must(&rig, "btn|Start|https://example.com"); _ = try go(&rig, .live, "crawl-view", .{}); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "crawl-stop", .{})); _ = try go(&rig, .force, "crawl-stop", .{}); try must(&rig, "btn|Stop crawl"); _ = try go(&rig, .live, "batch-send", .{ .text = "https://a.co" }); try must(&rig, "btn|Submit|https://a.co"); const pth = try rig.absOf("urls.txt"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/urls.txt", .{rig.tmpz.sub_path}), .data = "https://a.co\n" }); _ = try go(&rig, .live, "batch-file", .{ .photo = pth }); try must(&rig, "file|1"); _ = try go(&rig, .live, "browser-view", .{}); _ = try go(&rig, .live, "proxy-view", .{}); }
test "data and money: views, export, risky purchases need force" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "usage-view", .{}); _ = try go(&rig, .live, "analytics-view", .{}); _ = try go(&rig, .live, "logs-view", .{}); _ = try go(&rig, .live, "report-export", .{}); try must(&rig, "btn|Export"); _ = try go(&rig, .live, "plan-view", .{}); _ = try go(&rig, .live, "invoice-list", .{}); _ = try go(&rig, .live, "invoice-get", .{}); try must(&rig, "btn|Download invoice"); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "plan-change", .{ .opt = "Business" })); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "topup-buy", .{})); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "sub-cancel", .{})); _ = try go(&rig, .force, "plan-change", .{ .opt = "Business" }); try must(&rig, "btn|Business"); try must(&rig, "btn|Confirm|"); _ = try go(&rig, .force, "topup-buy", .{}); try must(&rig, "btn|Buy|"); _ = try go(&rig, .force, "payment-open", .{}); try must(&rig, "btn|Update payment method"); _ = try go(&rig, .force, "sub-cancel", .{}); try must(&rig, "btn|Confirm cancellation"); }
test "access: keys, team, webhooks, integrations" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "key-create", .{ .title = "ci-key" }); try must(&rig, "btn|Save|ci-key|"); _ = try go(&rig, .live, "key-rename", .{ .title = "ci-key-2" }); try must(&rig, "btn|Rename"); _ = try go(&rig, .live, "key-cap", .{ .price = "500" }); try must(&rig, "btn|Save cap||500"); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "key-revoke", .{})); _ = try go(&rig, .force, "key-revoke", .{}); try must(&rig, "btn|Delete key"); _ = try go(&rig, .live, "team-invite", .{ .to = "bob@example.com", .opt = "Admin" }); try must(&rig, "opt|Role=Admin"); try must(&rig, "btn|Send invite|bob@example.com"); _ = try go(&rig, .force, "team-remove", .{ .to = "ann@example.com" }); try must(&rig, "btn|Remove member"); _ = try go(&rig, .live, "webhook-add", .{ .url = "https://hook.example/x" }); try must(&rig, "btn|Save|https://hook.example/x"); _ = try go(&rig, .force, "webhook-drop", .{}); try must(&rig, "btn|Delete webhook"); _ = try go(&rig, .live, "integ-view", .{}); }
test "settings and help: alerts on then off, extra email, docs search, support, feedback, any page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "notif-usage-on", .{}); try must(&rig, "tog|Usage alerts=on"); _ = try go(&rig, .live, "notif-email-add", .{ .to = "ops@example.com" }); try must(&rig, "btn|Save|ops@example.com"); _ = try go(&rig, .live, "prefs-view", .{}); _ = try go(&rig, .live, "secu-view", .{}); _ = try go(&rig, .live, "docs-open", .{}); _ = try go(&rig, .live, "docs-search", .{ .text = "api key" }); try must(&rig, "key|Search=api key"); _ = try go(&rig, .live, "support-send", .{ .title = "Hello", .text = "Need help" }); try must(&rig, "btn|Send|Hello|Need help"); _ = try go(&rig, .live, "feedback-send", .{ .text = "Great" }); try must(&rig, "btn|Send|Great"); _ = try go(&rig, .live, "page-open", .{ .url = "/usage" }); }
test "caps apply per kind and a failed run keeps the key free" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_acct_dayz = 1; _ = try go(&rig, .live, "login", .{}); try std.testing.expectError(error.CapHit, go(&rig, .live, "login", .{})); rig.conf.retr_coun_maxz = 1; var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const cfgz = @import("cf-conf-load.zig"); const ovr = try cfgz.confParse(aren.allocator(), "{\"labl_over\":{\"supp_send\":[\"zzz no such\"]}}"); rig.conf.labl_over = ovr.labl_over; try std.testing.expectError(error.NoElement, go(&rig, .live, "feedback-send", .{ .text = "x" })); }
